function strict<T extends object>(facts: Partial<T>): T { return new Proxy(facts, { get(target, key) { if (!(key in target))
        throw new Error(`Unexpected port ${String(key)}`); return Reflect.get(target, key); } }) as T; }
const owner: Row = { id: 'obligation', status: 'approved', version: 2, created_by: 'creator', approved_by: 'approver', return_requested_by: 'requester', return_date: '2026-09-01', return_number: 'RETURN-1', direction: 'outgoing', currency: 'USD', chart_id: 'chart', balance_account_id: 'balance', outstanding_minor: 3000, base_outstanding_minor: 9000, beneficiary_name: '=Customer', beneficiary_account: 'beneficiary' };
