 body.enqueue(new TextEncoder().encode(JSON.stringify(receipt)));body.close();
 await expect(retry).rejects.toMatchObject({code:'WORK_CONTEXT_CHANGED'});expect(saved).toEqual([]);
 node.dataset.workRevision='7';node.dataset.workStale='false';expect(request.hasAttempt(url,input.body)).toBe(true);expect(request.completion(url,input.body)?.formEditVersion).toBe('submitted-evidence');
